{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if set(case) - {"nodes", "required_symbols", "_case_nonce", "schema_version", "task_id", "registry_id"}:
        raise ValueError("unexpected case field")
    nodes = case.get("nodes")
    required_symbols = case.get("required_symbols")
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("nodes and required_symbols are required lists")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required symbols must be strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("required symbols must be unique")

    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
        if not required_fields.issubset(node):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id or node_id in by_id:
            raise ValueError("node ids must be unique nonempty strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("nodes must form a tree with one root")
    root_id = roots[0]["id"]
    children = {node_id: set() for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node["id"]:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("parent and child depths are inconsistent")
        children[parent].add(node["id"])
    if any(symbol not in {node["symbol"] for node in nodes} for symbol in required_symbols):
        raise ValueError("a required symbol is absent")

    retained = set(by_id)
    removals = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required_symbols:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[item]["symbol"] for item in retained if item != node_id}
        if all(symbol in remaining_symbols for symbol in required_symbols):
            retained.remove(node_id)
            removals.append(node_id)

    return {"removed_node_ids": removals, "retained_node_ids": sorted(retained)}
"}
